#include "../../04-图论/割树GomoryHu.cpp"
int main(){mt19937 r(17);for(int t=0;t<200;t++){int n=2+r()%7;vector<array<ll,3>> e;for(int i=0;i<n;i++)for(int j=0;j<i;j++)e.push_back({i,j,r()%10});auto tree=gomory_hu(n,e);vector<vector<pair<int,ll>>> g(n);for(auto [u,v,w]:tree)g[u].push_back({v,w}),g[v].push_back({u,w});for(int a=0;a<n;a++)for(int b=0;b<a;b++){ll best=LLONG_MAX;for(int s=0;s<(1<<n);s++)if((s>>a&1)&&!(s>>b&1)){ll z=0;for(auto [u,v,w]:e)if(((s>>u)^(s>>v))&1)z+=w;best=min(best,z);}auto dfs=[&](auto&&dfs,int u,int p,ll z)->ll{if(u==b)return z;for(auto [v,w]:g[u])if(v!=p){ll ans=dfs(dfs,v,u,min(z,w));if(ans>=0)return ans;}return -1;};assert(dfs(dfs,a,-1,LLONG_MAX)==best);}}}
